# feature scalingimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')clownfish_data_known_sex = clownfish_data[(clownfish_data['Status'].isin(['M','F']))]clownfish_data_unknown_sex = clownfish_data[(clownfish_data['Status'].isin(['D','E','EP','S']))]clown_x = clownfish_data_known_sex[['mass_final_cm','Log_11KT']]clown_y = clownfish_data_known_sex[['Status']]   clown_x_test = clownfish_data_unknown_sex[['mass_final_cm','Log_11KT']]## first, impute the data# rather than what the book says, I want to do my linear regression idea#first, fit linear regression modelfrom sklearn.linear_model import LinearRegressionclown_x_dropna = clown_x.dropna(axis = 0)imputation_model = LinearRegression()imputation_model.fit(clown_x_dropna[['mass_final_cm']], clown_x_dropna[['Log_11KT']])# predict the 11kt valuesdata_to_predict = [[clown_x['mass_final_cm'][8]], [clown_x['mass_final_cm'][9]]]predicted_kt = imputation_model.predict(data_to_predict)clown_x['Log_11KT'][8] = predicted_kt[[0]]clown_x['Log_11KT'][9] = predicted_kt[[1]]### min max scalingfrom sklearn.preprocessing import MinMaxScalermms = MinMaxScaler()clown_x_norm = mms.fit_transform(clown_x) # this scaling makes it such that the lowest value is 0 and hte  #highest is 1  # standardization from sklearn.preprocessing import StandardScalerscaler = StandardScaler()scaler.fit(clown_x)clown_x_std = scaler.transform(clown_x)### L1 Regualrization ##### This is supported by logistic regression, so let me run that quicklyfrom sklearn.preprocessing import LabelEncoderclass_le = LabelEncoder()clown_y_labeled = class_le.fit_transform(clownfish_data_known_sex['Status'])##logistic ##from sklearn.linear_model import LogisticRegressionlog_model = LogisticRegression(penalty ='l1', # specify l1 regularization                               solver = 'liblinear', #not sure what this does                               C =1                               )log_model.fit(clown_x, clown_y_labeled)log_model.predict(clown_x_test) # predicts basically all males# that being said, this is an example with the only two variables I have for ALL sexes, so I cant# rely on gonadal data as much